const KAZAP_DEBUG=false;const logger={log:(...args)=>{if(KAZAP_DEBUG)console.log(...args)},info:(...args)=>{if(KAZAP_DEBUG)console.info(...args)},warn:(...args)=>{if(KAZAP_DEBUG)console.warn(...args)},error:(...args)=>console.error(...args)};(function(){if(!("serviceWorker"in navigator))return;let refreshing=false;window.addEventListener("load",async()=>{try{const reg=await navigator.serviceWorker.register("/sw.js",{scope:"/"});logger.log("SW offline (sw.js) enregistré :",reg);reg.update();document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")reg.update()})}catch(err){logger.warn("Erreur enregistrement sw.js :",err.message)}});navigator.serviceWorker.addEventListener("controllerchange",()=>{if(refreshing)return;refreshing=true;window.location.reload()})})();
